plist_t *parse_string_node(const char **bnode, uint64_t size) {
    // Allocate memory for the new string and the plist node
    char *str = (char *)malloc(size + 1);
    if (!str) {
        return NULL; // Allocation failure
    }

    // Copy the string data from the byte node
    memcpy(str, *bnode, size);
    str[size] = '\0'; // Null-terminate the string

    // Create the new plist node with the string data
    plist_t *node = plist_new_string(str);

    // Free the allocated string since it is now owned by the plist node
    free(str);

    return node;
}

plist_t* parse_string_node(const char **bnode, uint64_t size) {
    char *str;
    plist_t *node;

    str = (char *)malloc(size + 1);
    if (!str)
        return NULL;

    for (uint64_t i = 0; i < size; i++)
        str[i] = *(*bnode)++;
    str[size] = '\0';

    node = plist_new_node();
    if (!node) {
        free(str);
        return NULL;
    }

    node->type = PLIST_STRING;
    node->string = str;
    node->length = size;

    return node;
}

